import * as privacyKit from "privacy-kit";
import { afterAll, afterEach, beforeAll, describe, expect, it } from "vitest";

import { auth } from "@/app/auth/auth";
import { db } from "@/storage/db";
import { createLightSqliteHarness, type LightSqliteHarness } from "@/testkit/lightSqliteHarness";

const MASTER_SECRET = "compat-probe-0";

// Generated by the immutable privacy-kit@0.0.25 npm artifact under Node 22
// with MASTER_SECRET above. `remote-dev` currently emits the same no-epoch
// signed-session payload shape.
const LEGACY_NO_EPOCH_TOKEN =
    "eyJhbGciOiJFZERTQSJ9.eyJzdWIiOiJsZWdhY3ktbm9kZS11c2VyIiwicHJvdmVuYW5jZSI6InByaXZhY3kta2l0LTAuMC4yNS1ub2RlIiwiaWF0Ijo5NDY2ODQ4MDAsIm5iZiI6OTQ2Njg0ODAwLCJpc3MiOiJoYW5keSIsImp0aSI6ImM5YjFiMTNjLTk5MjUtNDBmYy1iMDE5LWFlMzRiNDg2NzUxNyJ9.fxMFx-QExdVNDwOMMXIo34aVn_YoWk9gH5w_AfAcE0yh6xxR2dsVfizBJ1zix6ZygEPgQpv_RIFE-5h9xf-OCw";

describe("auth (token epoch)", () => {
    let harness: LightSqliteHarness;

    beforeAll(async () => {
        harness = await createLightSqliteHarness({
            tempDirPrefix: "happier-auth-token-epoch-",
            initAuth: true,
            env: {
                HANDY_MASTER_SECRET: MASTER_SECRET,
                AUTH_TOKEN_CACHE_MAX_ENTRIES: "32",
                AUTH_REQUIRED_LOGIN_PROVIDERS: "",
            },
        });
    }, 120_000);

    afterEach(async () => {
        await db.account.deleteMany();
    });

    afterAll(async () => {
        await harness.close();
    });

    it("rejects an old signed token immediately after its warmed cache entry's account epoch advances", async () => {
        const account = await db.account.create({
            data: { publicKey: "token-epoch-warm-cache" },
            select: { id: true },
        });
        const token = await auth.createToken(account.id);
        expect(auth.getCacheStats().size).toBe(0);

        await expect(auth.verifyToken(token)).resolves.toMatchObject({ userId: account.id });
        expect(auth.getCacheStats().size).toBeGreaterThan(0);

        await db.account.update({
            where: { id: account.id },
            data: { tokenEpoch: { increment: 1 } },
        });

        await expect(auth.verifyToken(token)).resolves.toBeNull();
    });

    it("rejects a cold cryptographically valid token minted at an older epoch", async () => {
        const account = await db.account.create({
            data: { publicKey: "token-epoch-cold-cache" },
            select: { id: true },
        });
        const generator = await privacyKit.createPersistentTokenGenerator({
            service: "handy",
            seed: MASTER_SECRET,
        });
        const token = await generator.new({
            user: account.id,
            extras: { tokenEpoch: 0 },
        });

        await db.account.update({
            where: { id: account.id },
            data: { tokenEpoch: { increment: 1 } },
        });

        await expect(auth.verifyToken(token)).resolves.toBeNull();
    });

    it("treats the predecessor's no-epoch token as epoch zero before and after a zero-to-one bump", async () => {
        const account = await db.account.create({
            data: {
                id: "legacy-node-user",
                publicKey: "token-epoch-legacy-no-claim",
            },
            select: { id: true },
        });

        await expect(auth.verifyToken(LEGACY_NO_EPOCH_TOKEN)).resolves.toEqual({
            userId: account.id,
            extras: { provenance: "privacy-kit-0.0.25-node" },
        });

        await db.account.update({
            where: { id: account.id },
            data: { tokenEpoch: { increment: 1 } },
        });

        await expect(auth.verifyToken(LEGACY_NO_EPOCH_TOKEN)).resolves.toBeNull();
    });

    it("mints a token at the account's current epoch after a bump", async () => {
        const account = await db.account.create({
            data: { publicKey: "token-epoch-new-token" },
            select: { id: true },
        });
        await db.account.update({
            where: { id: account.id },
            data: { tokenEpoch: { increment: 1 } },
        });

        const token = await auth.createToken(account.id);
        const generator = await privacyKit.createPersistentTokenGenerator({
            service: "handy",
            seed: MASTER_SECRET,
        });
        const verifier = await privacyKit.createPersistentTokenVerifier({
            service: "handy",
            publicKey: Uint8Array.from(generator.publicKey),
        });

        await expect(verifier.verify(token)).resolves.toMatchObject({
            user: account.id,
            extras: { tokenEpoch: 1 },
        });
        await expect(auth.verifyToken(token)).resolves.toMatchObject({ userId: account.id });
    });

    it("increments the persisted epoch for sign out everywhere without relying on cache eviction", async () => {
        const account = await db.account.create({
            data: { publicKey: "token-epoch-sign-out-everywhere" },
            select: { id: true },
        });
        const token = await auth.createToken(account.id);
        await expect(auth.verifyToken(token)).resolves.toMatchObject({ userId: account.id });

        await expect(auth.signOutEverywhere(account.id)).resolves.toBe(1);
        await expect(db.account.findUnique({
            where: { id: account.id },
            select: { tokenEpoch: true },
        })).resolves.toEqual({ tokenEpoch: 1 });
        await expect(auth.verifyToken(token)).resolves.toBeNull();
    });
});
